// Generated by `pnpm nx g @app/generators:action routing.dlx-sources`. Requests go through the real router
// with createTestEngine().inject. They fail until createRoutingDlxSourcesAction is implemented; do not weaken them.
import { routingDlxSources } from '@app/contracts';
import { createRoleAuthorizer } from '@app/kernel';
import {
  createRoutingDlxSourcesAction,
  createTopologyFakeDeps,
} from '@app/svc-topology';
import { afterEach, describe, expect, it } from 'vitest';

import { createTestEngine, type TestEngine } from '../create-test-engine.ts';

const subject = () =>
  createRoutingDlxSourcesAction(
    createTopologyFakeDeps({ ownerId: 'local-token' }),
  );
const def = routingDlxSources;
const validBody = { vhost: '/', queue: 'orders.dlq' };
let engine: TestEngine;

afterEach(async () => {
  await engine.close();
});

describe('POST /connections/{cid}/routing/dlx-sources', () => {
  it('M1-20 G-1 the route runs routing.dlx-sources and answers in the shape of the contract', async () => {
    engine = createTestEngine({ actions: [subject()] });
    const answer = await engine.inject({
      method: 'POST',
      path: '/connections/c1/routing/dlx-sources',
      payload: validBody,
    });

    expect(answer.statusCode).toBe(200);
    expect(def.output.safeParse(answer.json()).success).toBe(true);
  });

  it('M1-20 G-2 a request without the launch token is refused and nothing runs', async () => {
    engine = createTestEngine({ actions: [subject()] });

    const answer = await engine.inject({
      method: 'POST',
      path: '/connections/c1/routing/dlx-sources',
      authenticated: false,
    });

    expect(answer.statusCode).toBe(401);
    expect(engine.audit.attempts).toEqual([]);
  });

  it('M1-20 G-3 a caller that does not hold broker.read gets 403 and nothing runs', async () => {
    engine = createTestEngine({
      actions: [subject()],
      authorizer: createRoleAuthorizer({}),
    });
    const answer = await engine.inject({
      method: 'POST',
      path: '/connections/c1/routing/dlx-sources',
      payload: validBody,
    });

    expect(answer.statusCode).toBe(403);
    expect(answer.json()).toMatchObject({ code: 'FORBIDDEN_RBAC' });
    expect(engine.audit.attempts).toEqual([]);
    expect(engine.writeCalls).toEqual([]);
  });

  it('M1-20 G-4 input that breaks the contract is a 400 Problem and nothing runs', async () => {
    engine = createTestEngine({ actions: [subject()] });
    const answer = await engine.inject({
      method: 'POST',
      path: '/connections/c1/routing/dlx-sources',
      payload: { unexpected: true },
    });

    expect(answer.statusCode).toBe(400);
    expect(answer.json()).toMatchObject({ code: 'VALIDATION_FAILED' });
    expect(engine.audit.attempts).toEqual([]);
  });

  it('M1-20 G-5 another method on the same path is 405', async () => {
    engine = createTestEngine({ actions: [subject()] });

    const answer = await engine.inject({
      method: 'GET',
      path: '/connections/c1/routing/dlx-sources',
    });

    expect(answer.statusCode).toBe(405);
    expect(answer.headers.allow).toBe('POST');
  });
});
